#include <vector>
#include <unordered_set>

using namespace std;

class Solution {
public:
    bool hasValidPath(vector<vector<char>>& grid) {
        int m = grid.size();
        int n = grid[0].size();

        if ((m + n - 1) % 2 != 0) return false;
        if (grid[0][0] == ')' || grid[m - 1][n - 1] == '(') return false;

        int max_k = (m + n - 1) / 2;

        vector<vector<unordered_set<int>>> dp(m, vector<unordered_set<int>>(n));

        int start_val = (grid[0][0] == '(') ? 1 : -1;
        dp[0][0].insert(start_val);

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i == 0 && j == 0) continue;

                int val = (grid[i][j] == '(') ? 1 : -1;

                vector<int> prev_sets;
                if (i > 0) {
                    for (int k : dp[i - 1][j]) {
                        prev_sets.push_back(k);
                    }
                }
                if (j > 0) {
                    for (int k : dp[i][j - 1]) {
                        prev_sets.push_back(k);
                    }
                }

                for (int k : prev_sets) {
                    int new_k = k + val;
                    if (new_k >= 0 && new_k <= max_k) {
                        dp[i][j].insert(new_k);
                    }
                }
            }
        }

        return dp[m - 1][n - 1].count(0);
    }
};
